class Solution {
  public int countPairs(List<List<Integer>> coordinates, int k) {
    Map<Long, Integer> seen = new HashMap<>();
    int pairs = 0;
    for (List<Integer> p : coordinates) {
      int x = p.get(0), y = p.get(1);
      // distance is (x1 ^ x2) + (y1 ^ y2): split k between the two xors
      for (int part = 0; part <= k; part++) {
        long key = ((long) (x ^ part) << 32) | (y ^ (k - part));
        pairs += seen.getOrDefault(key, 0);
      }
      seen.merge(((long) x << 32) | y, 1, Integer::sum);
    }
    return pairs;
  }
}
